# Explicit original-scale least-squares conventions make open regression checks reproducible.
def fitdata(times,observations,offset):
 ts=np.array(times,dtype=float);ys=np.array(observations,dtype=float)-offset
 ef=lambda tt,a,k:a*np.exp(k*tt);lf=lambda tt,L,B,k:L/(1+B*np.exp(-k*tt))
 ex,_=curve_fit(ef,ts,ys,p0=[max(10,ys[0]),.03],bounds=([0,0],[np.inf,1]),maxfev=100000,ftol=1e-12,xtol=1e-12,gtol=1e-12)
 lg,_=curve_fit(lf,ts,ys,p0=[max(ys)*1.1,10,.1],bounds=([0,0,0],[np.inf,np.inf,1]),maxfev=100000,ftol=1e-12,xtol=1e-12,gtol=1e-12)
 ep=offset+ef(ts,*ex);lp=offset+lf(ts,*lg)
 return ts,ys,ex,lg,ep,lp
